// ===========================
// 制度の計算機 — 所得税（年末調整）の値の表（値・出典・確認日をセットで）
// 令和8年分（2026 年）と、比べるための令和7年分（2025 年）。
// どの値も国税庁「令和○年分 年末調整のしかた」の原文（PDF）を読んで写した。ページは冊子のページ番号。
// 給与所得控除後の給与等の金額の表は、PDF から機械で取り出した lib/kyuyo-table-<年>.js にある
// （tools/extract-kyuyo-table.mjs。表と計算の規則が全行で合うことを tests/ で確かめている）。
// 毎年 9 月ごろ国税庁が翌年版を出したら、同じ形で年を足して CHECKED を更新する。
// ブラウザでは window.TaxValues、Node（テスト）では module.exports で使う
// ===========================
(function (root) {
  'use strict';

  var CHECKED = '2026-09-24';   // 下の出典を最後に原文で確かめた日
  var BASE8 = 'https://www.nta.go.jp/publication/pamph/gensen/nencho2026/';
  var BASE7 = 'https://www.nta.go.jp/publication/pamph/gensen/nencho2025/';

  // 生命保険料の計算式（支払った金額が upTo 以下なら 金額 × rate ＋ add。1 円未満は切り上げ。最後の行を超えたら cap）
  var SEIMEI_SHIKI_1 = { bands: [[20000, 1, 0], [40000, 0.5, 10000], [80000, 0.25, 20000]], cap: 40000 };   // 計算式Ⅰ（新・介護医療・新個人年金）
  var SEIMEI_SHIKI_2 = { bands: [[30000, 1, 0], [60000, 0.5, 15000], [120000, 0.25, 30000]], cap: 60000 };  // 計算式Ⅱ（23 歳未満の扶養親族あり・新生命保険料）
  var SEIMEI_SHIKI_3 = { bands: [[25000, 1, 0], [50000, 0.5, 12500], [100000, 0.25, 25000]], cap: 50000 };  // 計算式Ⅲ（旧生命・旧個人年金）

  // 算出所得税額の速算表（令和7年分・令和8年分とも同じ）: [課税給与所得金額がこの額以下, 税率（%）, 控除額]
  var SOKUSAN = [
    [1950000, 5, 0],
    [3300000, 10, 97500],
    [6950000, 20, 427500],
    [9000000, 23, 636000],
    [18000000, 33, 1536000],
    [18050000, 40, 2796000],
  ];

  var YEARS = {
    2026: {
      year: 2026,
      label: '令和8年分',
      book: '令和8年分 年末調整のしかた',
      CHECKED: CHECKED,
      SOURCES: [
        { key: 'index', label: '国税庁「令和8年分 年末調整のしかた」', url: BASE8 + '01.htm', pages: '' },
        { key: 'changes', label: '昨年と比べて変わった点（基礎控除の引上げ・給与所得控除の最低保障額 74 万円・扶養親族等の所得要件・23 歳未満の扶養親族がいる場合の生命保険料控除）', url: BASE8 + 'pdf/102.pdf', pages: '3〜4 ページ' },
        { key: 'fuyo', label: '扶養親族・障害者・寡婦・ひとり親・勤労学生の要件', url: BASE8 + 'pdf/105.pdf', pages: '8〜15 ページ' },
        { key: 'haigusha', label: '基礎控除・配偶者控除・配偶者特別控除・特定親族特別控除の要件', url: BASE8 + 'pdf/106.pdf', pages: '16〜20 ページ' },
        { key: 'hoken', label: '生命保険料控除（計算式Ⅰ〜Ⅲ・限度額）・地震保険料控除', url: BASE8 + 'pdf/107.pdf', pages: '24〜26 ページ' },
        { key: 'nenzei', label: '年税額の計算（課税給与所得金額の 1,000 円未満切り捨て・住宅借入金等特別控除・102.1%・100 円未満切り捨て）', url: BASE8 + 'pdf/109.pdf', pages: '35〜39 ページ' },
        { key: 'kyuyo', label: '令和8年分の年末調整等のための給与所得控除後の給与等の金額の表', url: BASE8 + 'pdf/114.pdf', pages: '47〜54 ページ' },
        { key: 'tables', label: '算出所得税額の速算表・配偶者控除等の一覧表・基礎控除額の表・扶養控除額等の表・特定親族特別控除額の表', url: BASE8 + 'pdf/115.pdf', pages: '55〜56 ページ' },
        { key: 'rei', label: '年末調整の設例（源泉徴収簿の記入例）', url: BASE8 + 'pdf/110rei.pdf', pages: '57〜59 ページ' },
      ],

      maxIncome: 20000000,          // 給与の収入金額がこれを超えると年末調整の対象外（114.pdf の表の終わり）
      maxTaxable: 18050000,         // 課税給与所得金額がこれを超えると年末調整の対象外（115.pdf 55 ページ）
      // 基礎控除: [本人の合計所得金額がこの額以下, 控除額]。最後を超えたら 0（115.pdf 56 ページ）
      kiso: [[4890000, 1040000], [6550000, 670000], [23500000, 620000], [24000000, 480000], [24500000, 320000], [25000000, 160000]],
      // 扶養親族・同一生計配偶者の所得要件（合計所得金額がこの額以下。102.pdf 4 ページ）
      fuyoLimit: 620000,
      fuyo: { ippan: 380000, tokutei: 630000, rojin: 480000, dokyoRoshin: 580000 },   // 115.pdf 56 ページ
      shogai: { ippan: 270000, tokubetsu: 400000, dokyoTokubetsu: 750000 },
      kafu: 270000, hitorioya: 350000, kafuIncomeLimit: 5000000,                          // 105.pdf 13〜14 ページ
      kinro: 270000, kinroLimit: 890000,                                                   // 105.pdf 14 ページ
      // 配偶者控除・配偶者特別控除（115.pdf 55 ページ）。本人の合計所得金額 900 万以下／950 万以下／1,000 万以下の 3 列
      haigushaHonnin: [9000000, 9500000, 10000000],
      haigusha: [380000, 260000, 130000],
      haigushaRojin: [480000, 320000, 160000],
      // 配偶者特別控除: [配偶者の合計所得金額がこの額以下, [3 列の控除額]]（fuyoLimit 超から）
      haigushaTokubetsu: [
        [950000, [380000, 260000, 130000]],
        [1000000, [360000, 240000, 120000]],
        [1050000, [310000, 210000, 110000]],
        [1100000, [260000, 180000, 90000]],
        [1150000, [210000, 140000, 70000]],
        [1200000, [160000, 110000, 60000]],
        [1250000, [110000, 80000, 40000]],
        [1300000, [60000, 40000, 20000]],
        [1330000, [30000, 20000, 10000]],
      ],
      // 特定親族特別控除: [特定親族の合計所得金額がこの額以下, 控除額]（fuyoLimit 超から。115.pdf 56 ページ）
      tokuteiShinzoku: [[850000, 630000], [900000, 610000], [950000, 510000], [1000000, 410000], [1050000, 310000], [1100000, 210000], [1150000, 110000], [1200000, 60000], [1230000, 30000]],
      // 生命保険料控除（107.pdf 24 ページ）
      seimei: { shiki1: SEIMEI_SHIKI_1, shiki2: SEIMEI_SHIKI_2, shiki3: SEIMEI_SHIKI_3, u23Special: true, bothCap: 40000, bothCapU23: 60000, total: 120000 },
      // 地震保険料控除（107.pdf 26 ページ）: 旧長期損害保険料は 1 万以下全額、2 万以下 × 1/2 ＋ 5,000、超は 15,000。合計 5 万まで
      jishin: { cap: 50000, oldLong: { bands: [[10000, 1, 0], [20000, 0.5, 5000]], cap: 15000 }, total: 50000 },
      sokusan: SOKUSAN,
      fukkou: 1021,                 // 年調所得税額 × 102.1%（1,021 / 1,000）、100 円未満切り捨て（109.pdf 39 ページ）
      // 所得金額調整控除（このツールの画面では計算しない。設例の再現用）: （給与の総額（1,000 万が上限）− 850 万）× 10%、1 円未満切り上げ（109.pdf 37 ページ）
      chosei: { from: 8500000, capIncome: 10000000, pct: 10 },
    },

    2025: {
      year: 2025,
      label: '令和7年分',
      book: '令和7年分 年末調整のしかた',
      CHECKED: CHECKED,
      SOURCES: [
        { key: 'index', label: '国税庁「令和7年分 年末調整のしかた」', url: BASE7 + '01.htm', pages: '' },
        { key: 'changes', label: '昨年と比べて変わった点（基礎控除の見直し・給与所得控除の最低保障額 65 万円・特定親族特別控除の創設）', url: BASE7 + 'pdf/102.pdf', pages: '3 ページ〜' },
        { key: 'fuyo', label: '扶養親族・障害者・寡婦・ひとり親・勤労学生の要件', url: BASE7 + 'pdf/105.pdf', pages: '10〜17 ページ' },
        { key: 'hoken', label: '生命保険料控除・地震保険料控除', url: BASE7 + 'pdf/107.pdf', pages: '22〜29 ページ' },
        { key: 'nenzei', label: '年税額の計算', url: BASE7 + 'pdf/109.pdf', pages: '35〜39 ページ' },
        { key: 'kyuyo', label: '令和7年分の年末調整等のための給与所得控除後の給与等の金額の表', url: BASE7 + 'pdf/114.pdf', pages: '47〜54 ページ' },
        { key: 'tables', label: '算出所得税額の速算表・配偶者控除等の一覧表・基礎控除額の表・扶養控除額等の表・特定親族特別控除額の表', url: BASE7 + 'pdf/115.pdf', pages: '55〜56 ページ' },
      ],

      maxIncome: 20000000,
      maxTaxable: 18050000,
      kiso: [[1320000, 950000], [3360000, 880000], [4890000, 680000], [6550000, 630000], [23500000, 580000], [24000000, 480000], [24500000, 320000], [25000000, 160000]],
      fuyoLimit: 580000,
      fuyo: { ippan: 380000, tokutei: 630000, rojin: 480000, dokyoRoshin: 580000 },
      shogai: { ippan: 270000, tokubetsu: 400000, dokyoTokubetsu: 750000 },
      kafu: 270000, hitorioya: 350000, kafuIncomeLimit: 5000000,
      kinro: 270000, kinroLimit: 850000,
      haigushaHonnin: [9000000, 9500000, 10000000],
      haigusha: [380000, 260000, 130000],
      haigushaRojin: [480000, 320000, 160000],
      haigushaTokubetsu: [
        [950000, [380000, 260000, 130000]],
        [1000000, [360000, 240000, 120000]],
        [1050000, [310000, 210000, 110000]],
        [1100000, [260000, 180000, 90000]],
        [1150000, [210000, 140000, 70000]],
        [1200000, [160000, 110000, 60000]],
        [1250000, [110000, 80000, 40000]],
        [1300000, [60000, 40000, 20000]],
        [1330000, [30000, 20000, 10000]],
      ],
      tokuteiShinzoku: [[850000, 630000], [900000, 610000], [950000, 510000], [1000000, 410000], [1050000, 310000], [1100000, 210000], [1150000, 110000], [1200000, 60000], [1230000, 30000]],
      // 令和7年分には 23 歳未満の扶養親族がいる場合の特例がない（新旧合計の限度は 4 万円）
      seimei: { shiki1: SEIMEI_SHIKI_1, shiki2: null, shiki3: SEIMEI_SHIKI_3, u23Special: false, bothCap: 40000, bothCapU23: 40000, total: 120000 },
      jishin: { cap: 50000, oldLong: { bands: [[10000, 1, 0], [20000, 0.5, 5000]], cap: 15000 }, total: 50000 },
      sokusan: SOKUSAN,
      fukkou: 1021,
      chosei: { from: 8500000, capIncome: 10000000, pct: 10 },
    },
  };

  var TAX = {
    CHECKED: CHECKED,
    STALE_MONTHS: 12,             // 確認日からこの月数がたったら画面に注意を出す
    CURRENT: 2026,                // 画面で計算する年
    PREVIOUS: 2025,               // 比べる年
    years: YEARS,
  };

  // 給与所得控除後の給与等の金額の表（PDF から取り出したデータ）をつなぐ
  if (typeof module !== 'undefined' && module.exports) {
    YEARS[2026].kyuyoTable = require('./kyuyo-table-2026.js');
    YEARS[2025].kyuyoTable = require('./kyuyo-table-2025.js');
    module.exports = TAX;
  } else {
    var t = root.KyuyoTables || {};
    YEARS[2026].kyuyoTable = t[2026];
    YEARS[2025].kyuyoTable = t[2025];
    root.TaxValues = TAX;
  }
})(this);
